// ---------- Набор для рисования знаков ----------
const K = {
  W: s => `<svg viewBox="0 0 100 100">${s}</svg>`,
  tri: s => K.W(`<polygon points="50,7 95,89 5,89" fill="#fff" stroke="#d32f2f" stroke-width="8" stroke-linejoin="round"/>${s}`),
  red: s => K.W(`<circle cx="50" cy="50" r="42" fill="#fff" stroke="#d32f2f" stroke-width="10"/>${s}`),
  blue: s => K.W(`<circle cx="50" cy="50" r="46" fill="#1e5bb8" stroke="#fff" stroke-width="2"/>${s}`),
  sq: s => K.W(`<rect x="5" y="5" width="90" height="90" rx="8" fill="#1e5bb8" stroke="#fff" stroke-width="2"/>${s}`),
  end: s => K.W(`<circle cx="50" cy="50" r="44" fill="#fff" stroke="#333" stroke-width="2"/>${s}`),
  line: (d, c, w) => `<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}"/>`,
  // наконечник стрелки: остриё в (x,y); a — угол (0 вверх, 90 вправо, 180 вниз, 270 влево)
  head: (x, y, a, c, s = 12) => `<polygon points="${x},${y} ${x-s},${y+s*1.3} ${x+s},${y+s*1.3}" fill="${c}" transform="rotate(${a} ${x} ${y})"/>`,
  txt: (t, c, size = 34, y = 62, x = 50) => `<text x="${x}" y="${y}" font-size="${size}" font-weight="bold" fill="${c}" text-anchor="middle" font-family="Arial">${t}</text>`,
  slash: `<line x1="22" y1="22" x2="78" y2="78" stroke="#d32f2f" stroke-width="8"/>`,
  stripes: c => `<clipPath id="ce"><circle cx="50" cy="50" r="43"/></clipPath><g clip-path="url(#ce)">` +
    [-24, -12, 0, 12, 24].map(o => `<line x1="${10+o}" y1="${90+o}" x2="${90+o}" y2="${10+o}" stroke="${c}" stroke-width="3"/>`).join("") + `</g>`,
  car: (x, c) => `<rect x="${x-11}" y="47" width="22" height="15" rx="3" fill="${c}"/><rect x="${x-8}" y="38" width="16" height="11" rx="3" fill="${c}"/>` +
    `<rect x="${x-10}" y="61" width="5" height="6" fill="${c}"/><rect x="${x+5}" y="61" width="5" height="6" fill="${c}"/>`,
  truckRear: (x, c) => `<rect x="${x-12}" y="34" width="24" height="28" rx="2" fill="${c}"/><rect x="${x-11}" y="61" width="6" height="6" fill="${c}"/><rect x="${x+5}" y="61" width="6" height="6" fill="${c}"/>`,
  round: (cx, cy, r, c, w, s) => `<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="${c}" stroke-width="${w}"/>` +
    [90, 210, 330].map(t => { const a = t * Math.PI / 180; return K.head(+(cx + r*Math.cos(a)).toFixed(1), +(cy - r*Math.sin(a)).toFixed(1), -t, c, s); }).join(""),
  uturn: (c, w, s) => K.line("M62 80 V46 Q62 32 50 32 Q38 32 38 46 V56", c, w) + K.head(38, 72, 180, c, s),
  town: (bg, fg, crossed) => K.W(`<rect x="4" y="28" width="92" height="44" rx="4" fill="${bg}" stroke="${fg === "#fff" ? "#fff" : "#111"}" stroke-width="3"/>` +
    K.txt("CHIRCHIQ", fg, 15, 56) + (crossed ? `<line x1="10" y1="66" x2="90" y2="34" stroke="#d32f2f" stroke-width="6"/>` : ""))
};
