// Вопрос «что означает знак»: правильный вариант + 3 неверных (порядок перемешает приложение)
function SIGN(rule, img, okRu, okUz, badRu, badUz, eru, euz){
  Q(rule, img, SIGN_Q_RU, SIGN_Q_UZ, [okRu, ...badRu], [okUz, ...badUz], 0, eru, euz);
}

