// =====================================================================
// ПАРТИЯ 3: ДТП, пешеходы, пассажиры, спецтранспорт, расположение на дороге,
// регулируемые перекрёстки, автомагистрали, жилые зоны, спуски, маршрутный транспорт,
// буксировка, обучение, перевозка людей и грузов, велосипеды, разметка, первая помощь
// =====================================================================

// ---------- Картинки разметки (вид сверху, вы едете вверх по правой полосе) ----------
const MK = {
  road: s => K.W(`<rect x="2" y="2" width="96" height="96" rx="10" fill="#5b5f63"/>${s}`),
  wline: (x, w = 4, c = "#fff") => `<rect x="${x}" y="2" width="${w}" height="96" fill="${c}"/>`,
  dashes: (x, h, step, c = "#fff", w = 4) => { let s = ""; for (let y = 4; y < 98; y += step) s += `<rect x="${x}" y="${y}" width="${w}" height="${Math.min(h, 98 - y)}" fill="${c}"/>`; return s; },
  car: `<rect x="66" y="66" width="16" height="26" rx="4" fill="#1e88e5"/><rect x="68" y="72" width="12" height="7" rx="2" fill="#bbdefb"/>`,
  kerb: `<rect x="84" y="2" width="14" height="96" fill="#b0b5b9"/>`
};
const MIMG = {
  m1_1: MK.road(MK.wline(48) + MK.car),
  m1_3: MK.road(MK.wline(44) + MK.wline(52) + MK.car),
  m1_5: MK.road(MK.dashes(48, 12, 36) + MK.car),
  m1_6: MK.road(MK.dashes(48, 21, 28) + MK.car),
  m1_11: MK.road(MK.wline(44) + MK.dashes(52, 12, 24) + MK.car),
  m1_4: MK.road(MK.kerb + MK.wline(80, 4, "#fbc02d") + MK.dashes(36, 12, 36)),
  m1_10: MK.road(MK.kerb + MK.dashes(80, 12, 24, "#fbc02d") + MK.dashes(36, 12, 36)),
  m1_12: MK.road(MK.wline(48) + `<rect x="52" y="44" width="44" height="7" fill="#fff"/>` + MK.car),
  m1_13: MK.road(MK.wline(48) + [56, 66, 76, 86].map(x => `<polygon points="${x-4},42 ${x+4},42 ${x},54" fill="#fff"/>`).join("") + MK.car),
  m1_14_1: MK.road([8, 22, 36, 50, 64, 78].map(x => `<rect x="${x}" y="36" width="9" height="28" fill="#fff"/>`).join("")),
  m1_14_4: MK.road([8, 22, 36, 50, 64, 78].map((x, i) => `<rect x="${x}" y="36" width="9" height="28" fill="${i % 2 ? "#e53935" : "#fff"}"/>`).join("")),
  m1_17: MK.road(MK.kerb + MK.dashes(36, 12, 36) + `<polyline points="82,14 70,24 82,34 70,44 82,54 70,64 82,74 70,84" fill="none" stroke="#fbc02d" stroke-width="4"/>`)
};
const MARK_Q_RU = "Что означает эта разметка?", MARK_Q_UZ = "Bu chiziq nimani bildiradi?";
function MARK(rule, img, okRu, okUz, badRu, badUz, eru, euz){
  Q(rule, img, MARK_Q_RU, MARK_Q_UZ, [okRu, ...badRu], [okUz, ...badUz], 0, eru, euz);
}
// Вопрос с правильным ответом на первом месте (порядок перемешает приложение)
function Q1(rule, img, qru, quz, okRu, okUz, badRu, badUz, eru, euz){
  Q(rule, img, qru, quz, [okRu, ...badRu], [okUz, ...badUz], 0, eru, euz);
}

